BEGIN;
DO $$
DECLARE league uuid:=gen_random_uuid(); season uuid:=gen_random_uuid(); prior_season uuid; admin uuid:=gen_random_uuid();
  users uuid[]:=ARRAY[gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()];
  ids uuid[]; seeds jsonb; home uuid; away uuid; away2 uuid; away3 uuid; away4 uuid; prior_team uuid; m uuid; m2 uuid; m3 uuid; m4 uuid; bet uuid; offer uuid;
  request uuid:=gen_random_uuid(); receipt uuid; preview jsonb; hist jsonb; ratings jsonb; correction_request uuid:=gen_random_uuid();
  unlink_request uuid:=gen_random_uuid(); balances_before jsonb; journal_count bigint;
BEGIN
  INSERT INTO auth.users(id,email,raw_app_meta_data) VALUES(admin,'bet-admin@test.local','{"role":"admin"}');
  FOR n IN 1..4 LOOP INSERT INTO auth.users(id,email,raw_app_meta_data) VALUES(users[n],'bettor-'||n||'@test.local','{}'); END LOOP;
  IF EXISTS(SELECT 1 FROM auth.users u WHERE u.id=ANY(users) AND u.raw_app_meta_data->>'role'='admin') THEN RAISE EXCEPTION 'New users became admins'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin,'app_metadata',jsonb_build_object('role','admin'))::text,true);
  SELECT array_agg(id),jsonb_agg(jsonb_build_object('id',id,'name','Bets player '||n,'is_new',true,'initial_rating',1500)) INTO ids,seeds FROM (SELECT n,gen_random_uuid() id FROM generate_series(1,7)n)q;
  PERFORM public.create_league_atomic(league,'bet-test-'||league::text,'Bet tests',season,'Bet season',seeds,'[]','[]');
  PERFORM public.save_season_roster_atomic(season,ids);
  INSERT INTO public.teams(season_id,name,color) VALUES(season,'Home','#15803d') RETURNING id INTO home;
  INSERT INTO public.teams(season_id,name,color) VALUES(season,'Away','#1d4ed8') RETURNING id INTO away;
  INSERT INTO public.teams(season_id,name,color) VALUES(season,'Away 2','#1d4ed8') RETURNING id INTO away2;
  INSERT INTO public.teams(season_id,name,color) VALUES(season,'Away 3','#1d4ed8') RETURNING id INTO away3;
  FOR n IN 1..4 LOOP INSERT INTO public.players(name,team_id,pool_player_id,season_id) VALUES('Bets player '||n,CASE WHEN n<3 THEN home ELSE away END,ids[n],season); END LOOP;
  INSERT INTO public.matches(season_id,home_team_id,away_team_id,round_number,home_pool_player_ids,away_pool_player_ids) VALUES(season,home,away,1,ids[1:2],ids[3:4]) RETURNING id INTO m;
  INSERT INTO public.matches(season_id,home_team_id,away_team_id,round_number,home_pool_player_ids,away_pool_player_ids) VALUES(season,home,away2,2,ids[1:2],ids[3:4]) RETURNING id INTO m2;
  INSERT INTO public.matches(season_id,home_team_id,away_team_id,round_number,home_pool_player_ids,away_pool_player_ids) VALUES(season,home,away3,3,ids[1:2],ids[3:4]) RETURNING id INTO m3;
  -- Seed historical credits through the same allocation trigger as real prizes.
  INSERT INTO public.seasons(league_id,name,status) VALUES(league,'Historical prize','archived') RETURNING id INTO prior_season;
  INSERT INTO public.teams(season_id,name,color) VALUES(prior_season,'Prize team','#15803d') RETURNING id INTO prior_team;
  INSERT INTO public.pickle_awards(season_id,league_id,awarded_by,receipt) VALUES(prior_season,league,admin,'{}');
  FOR n IN 1..7 LOOP INSERT INTO public.pickle_allocations(season_id,pool_player_id,team_id,amount) VALUES(prior_season,ids[n],prior_team,CASE WHEN n=5 THEN 1000 ELSE 10000 END); END LOOP;
  PERFORM public.link_player_account(ids[5],'BETTOR-1@test.local');
  PERFORM public.link_player_account(ids[6],'bettor-2@test.local');
  PERFORM public.link_player_account(ids[7],'bettor-3@test.local');
  PERFORM public.link_player_account(ids[1],'bettor-4@test.local');
  BEGIN PERFORM public.link_player_account(ids[2],'bettor-1@test.local'); RAISE EXCEPTION 'Link reassigned'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_LINKED:%' THEN RAISE; END IF; END;
  EXECUTE 'SET LOCAL ROLE authenticated';
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[1])::text,true);
  IF (public.pickle_wallet(league)->>'balance')::numeric<>1000 THEN RAISE EXCEPTION 'Prize not credited'; END IF;
  BEGIN PERFORM public.link_player_account(ids[2],'bettor-1@test.local'); RAISE EXCEPTION 'Player linked account'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  BEGIN INSERT INTO public.pickle_wallets(league_id,pool_player_id,balance) VALUES(league,ids[2],1000000); RAISE EXCEPTION 'Direct mint allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  BEGIN PERFORM public.create_pickle_bet(m,home,1500,1000,gen_random_uuid()); RAISE EXCEPTION 'Invalid stake accepted'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_AMOUNT:%' THEN RAISE; END IF; END;
  BEGIN PERFORM public.create_pickle_bet(m,home,2000,1000,gen_random_uuid()); RAISE EXCEPTION 'Overspend allowed'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_FUNDS:%' THEN RAISE; END IF; END;
  bet:=public.create_pickle_bet(m,home,1000,5000,request);
  BEGIN PERFORM public.unlink_player_account(ids[5],'bettor-1@test.local',gen_random_uuid()); RAISE EXCEPTION 'Player unlinked an account'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin,'app_metadata',jsonb_build_object('role','admin'))::text,true);
  BEGIN PERFORM public.unlink_player_account(ids[5],'bettor-1@test.local',gen_random_uuid()); RAISE EXCEPTION 'Open offer unlinked'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_UNLINK_PENDING:%' THEN RAISE; END IF; END;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[1])::text,true);
  IF public.create_pickle_bet(m,home,1000,5000,request)<>bet THEN RAISE EXCEPTION 'Duplicate offer'; END IF;
  IF (public.pickle_wallet(league)->>'reserved')::numeric<>1000 OR (public.pickle_wallet(league)->>'available')::numeric<>0 THEN RAISE EXCEPTION 'Reservation wrong'; END IF;
  IF (SELECT count(*) FROM public.pickle_wallets WHERE league_id=league)<>1 THEN RAISE EXCEPTION 'Private wallets exposed'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[4])::text,true);
  BEGIN PERFORM public.accept_pickle_bet(bet,gen_random_uuid()); RAISE EXCEPTION 'Participant accepted'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_SPECTATOR:%' THEN RAISE; END IF; END;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[2])::text,true);
  request:=gen_random_uuid(); PERFORM public.accept_pickle_bet(bet,request); PERFORM public.accept_pickle_bet(bet,request);
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin,'app_metadata',jsonb_build_object('role','admin'))::text,true);
  BEGIN PERFORM public.unlink_player_account(ids[6],'bettor-2@test.local',gen_random_uuid()); RAISE EXCEPTION 'Accepted bettor unlinked'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_UNLINK_PENDING:%' THEN RAISE; END IF; END;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[2])::text,true);
  BEGIN PERFORM public.cancel_pickle_bet(bet); RAISE EXCEPTION 'Acceptor cancelled'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  BEGIN PERFORM public.confirm_pickle_settlement(m,'x',0); RAISE EXCEPTION 'Player confirmed payout'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[3])::text,true);
  BEGIN PERFORM public.accept_pickle_bet(bet,gen_random_uuid()); RAISE EXCEPTION 'Second acceptor'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_TAKEN:%' THEN RAISE; END IF; END;
  offer:=public.create_pickle_bet(m,away,1000,1000,gen_random_uuid());
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin,'app_metadata',jsonb_build_object('role','admin'))::text,true);
  UPDATE public.players SET is_present=true WHERE season_id=season;
  UPDATE public.matches SET live_status='playing',live_court_number=1 WHERE id=m;
  IF (SELECT state FROM public.pickle_bets WHERE id=offer)<>'cancelled' THEN RAISE EXCEPTION 'Open offer stayed after start'; END IF;
  UPDATE public.matches SET live_status='available',live_court_number=NULL WHERE id=m;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[3])::text,true);
  BEGIN PERFORM public.create_pickle_bet(m,home,1000,1000,gen_random_uuid()); RAISE EXCEPTION 'Started betting reopened'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_CLOSED:%' THEN RAISE; END IF; END;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin,'app_metadata',jsonb_build_object('role','admin'))::text,true);
  UPDATE public.matches SET status='completed',winner_team_id=home,home_score=11,away_score=7 WHERE id=m;
  IF (SELECT state FROM public.pickle_bets WHERE id=bet)<>'review' THEN RAISE EXCEPTION 'Payout was not held for review'; END IF;
  BEGIN PERFORM public.unlink_player_account(ids[5],'bettor-1@test.local',gen_random_uuid()); RAISE EXCEPTION 'Awaiting-review bettor unlinked'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_UNLINK_PENDING:%' THEN RAISE; END IF; END;
  BEGIN UPDATE public.seasons SET status='archived' WHERE id=season; RAISE EXCEPTION 'Unreviewed bets archived'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_REVIEW:%' THEN RAISE; END IF; END;
  preview:=public.pickle_settlement_preview(m);
  BEGIN PERFORM public.confirm_pickle_settlement(m,'stale',0); RAISE EXCEPTION 'Stale preview paid'; EXCEPTION WHEN serialization_failure THEN NULL; END;
  receipt:=public.confirm_pickle_settlement(m,preview->>'fingerprint',0);
  IF public.confirm_pickle_settlement(m,preview->>'fingerprint',0)<>receipt THEN RAISE EXCEPTION 'Duplicate payout'; END IF;
  BEGIN UPDATE public.matches SET winner_team_id=away,home_score=7,away_score=11 WHERE id=m; RAISE EXCEPTION 'Direct correction bypass'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_CORRECTION:%' THEN RAISE; END IF; END;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[1])::text,true);
  IF (public.pickle_wallet(league)->>'balance')::numeric<>6000 OR (public.pickle_wallet(league)->>'reserved')::numeric<>0 THEN RAISE EXCEPTION 'Unequal payout wrong'; END IF;
  -- Spend the winnings in a second match before correcting the first result.
  offer:=public.create_pickle_bet(m2,home,5000,1000,gen_random_uuid());
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[3])::text,true); PERFORM public.accept_pickle_bet(offer,gen_random_uuid());
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin,'app_metadata',jsonb_build_object('role','admin'))::text,true);
  UPDATE public.matches SET status='completed',winner_team_id=away2,home_score=2,away_score=11 WHERE id=m2;
  preview:=public.pickle_settlement_preview(m2); PERFORM public.confirm_pickle_settlement(m2,preview->>'fingerprint',0);
  preview:=public.pickle_settlement_preview(m);
  SELECT jsonb_agg(jsonb_build_object('pool_player_id',pool_player_id,'match_id',NULL,'rating',rating,'rating_deviation',rating_deviation,'sequence',0,'recorded_at',now())),
    jsonb_agg(jsonb_build_object('id',pool_player_id,'rating',rating,'rating_deviation',rating_deviation,'volatility',volatility)) INTO hist,ratings FROM public.league_players WHERE league_id=league;
  BEGIN
    PERFORM public.correct_pickle_match_result(league,m,'completed',away,7,11,ids[1:2],ids[3:4],NULL,'[]','[]',
      (SELECT revision FROM public.rating_state WHERE league_id=league),'Invalid replay payload',preview->>'fingerprint',1,gen_random_uuid());
    RAISE EXCEPTION 'Broken replay committed';
  EXCEPTION WHEN others THEN IF SQLERRM<>'Rating replacement payloads cannot be empty' THEN RAISE; END IF; END;
  IF (SELECT winner_team_id FROM public.matches WHERE id=m)<>home OR (SELECT count(*) FROM public.pickle_bet_settlements WHERE match_id=m)<>1 THEN RAISE EXCEPTION 'Correction rollback failed'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[1])::text,true);
  offer:=public.create_pickle_bet(m3,home,1000,1000,gen_random_uuid());
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin,'app_metadata',jsonb_build_object('role','admin'))::text,true);
  PERFORM public.correct_pickle_match_result(league,m,'completed',away,7,11,ids[1:2],ids[3:4],NULL,hist,ratings,
    (SELECT revision FROM public.rating_state WHERE league_id=league),'Recorded wrong side',preview->>'fingerprint',1,correction_request);
  IF (SELECT state FROM public.pickle_bets WHERE id=offer)<>'cancelled' THEN RAISE EXCEPTION 'Unfunded offer survived correction'; END IF;
  BEGIN PERFORM public.correct_pickle_match_result(league,m,'completed',home,11,7,ids[1:2],ids[3:4],NULL,hist,ratings,
    (SELECT revision FROM public.rating_state WHERE league_id=league),'Recorded wrong side',preview->>'fingerprint',1,correction_request); RAISE EXCEPTION 'Changed request replayed';
  EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_REQUEST:%' THEN RAISE; END IF; END;
  BEGIN PERFORM public.correct_pickle_match_result(league,m,'completed',home,11,7,ids[1:2],ids[3:4],NULL,hist,ratings,
    (SELECT revision FROM public.rating_state WHERE league_id=league),'Stale result review',preview->>'fingerprint',1,gen_random_uuid()); RAISE EXCEPTION 'Stale correction accepted';
  EXCEPTION WHEN serialization_failure THEN NULL; END;
  PERFORM public.correct_pickle_match_result(league,m,'completed',away,7,11,ids[1:2],ids[3:4],NULL,hist,ratings,
    (SELECT revision FROM public.rating_state WHERE league_id=league),'Recorded wrong side',preview->>'fingerprint',1,correction_request);
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[1])::text,true);
  IF (public.pickle_wallet(league)->>'balance')::numeric<>-5000 OR (public.pickle_wallet(league)->>'owed')::numeric<>5000 THEN RAISE EXCEPTION 'Correction debt wrong'; END IF;
  BEGIN PERFORM public.create_pickle_bet(m3,home,1000,1000,gen_random_uuid()); RAISE EXCEPTION 'Debt spent'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_FUNDS:%' THEN RAISE; END IF; END;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[2])::text,true);
  bet:=public.create_pickle_bet(m3,home,2000,1000,gen_random_uuid());
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[3])::text,true); PERFORM public.accept_pickle_bet(bet,gen_random_uuid());
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin,'app_metadata',jsonb_build_object('role','admin'))::text,true);
  UPDATE public.matches SET status='forfeit',winner_team_id=home WHERE id=m3;
  preview:=public.pickle_settlement_preview(m3); PERFORM public.confirm_pickle_settlement(m3,preview->>'fingerprint',0);
  IF (SELECT state FROM public.pickle_bets WHERE id=bet)<>'refunded' THEN RAISE EXCEPTION 'Forfeit paid instead of refund'; END IF;
  INSERT INTO public.teams(season_id,name,color) VALUES(season,'Changed lineup','#1d4ed8') RETURNING id INTO away4;
  INSERT INTO public.matches(season_id,home_team_id,away_team_id,round_number,home_pool_player_ids,away_pool_player_ids) VALUES(season,home,away4,4,ids[1:2],ids[3:4]) RETURNING id INTO m4;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[2])::text,true);
  bet:=public.create_pickle_bet(m4,home,2000,1000,gen_random_uuid());
  BEGIN PERFORM public.pickle_wallet(gen_random_uuid()); RAISE EXCEPTION 'Cross league wallet exposed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[3])::text,true); PERFORM public.accept_pickle_bet(bet,gen_random_uuid());
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin,'app_metadata',jsonb_build_object('role','admin'))::text,true);
  UPDATE public.player_pool SET name='Renamed spectator' WHERE id=ids[6];
  IF (SELECT state FROM public.pickle_bets WHERE id=bet)<>'accepted' THEN RAISE EXCEPTION 'Rename voided a bet'; END IF;
  UPDATE public.matches SET home_pool_player_ids=ARRAY[ids[1],ids[5]] WHERE id=m4;
  IF (SELECT state FROM public.pickle_bets WHERE id=bet)<>'void' THEN RAISE EXCEPTION 'Changed players did not void bet'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[2])::text,true);
  IF (public.my_player_account()->>'playerId')::uuid<>ids[6] OR (public.pickle_wallet(league)->>'reserved')::numeric<>0 THEN RAISE EXCEPTION 'Identity or released reservation wrong'; END IF;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin,'app_metadata',jsonb_build_object('role','admin'))::text,true);
  UPDATE public.matches SET status='forfeit',winner_team_id=home WHERE id=m4;
  EXECUTE 'RESET ROLE';
  -- Voiding a contract alone cannot bypass correction accounting.
  BEGIN
    UPDATE public.pickle_bets SET state='void' WHERE match_id=m AND state='settled';
    UPDATE public.matches SET status='scheduled',winner_team_id=NULL,home_score=NULL,away_score=NULL,result_recorded_at=NULL WHERE id=m;
    RAISE EXCEPTION 'Nonzero bet ledger allowed direct result reset';
  EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_CORRECTION:%' THEN RAISE; END IF; END;
  -- An already zero-net, fully voided test contract permits the real result later.
  UPDATE public.pickle_bets SET state='void' WHERE match_id=m3 AND state='refunded';
  UPDATE public.matches SET status='scheduled',winner_team_id=NULL,home_score=NULL,away_score=NULL,result_recorded_at=NULL WHERE id=m3;
  IF (SELECT betting_closed_at FROM public.matches WHERE id=m3) IS NULL THEN RAISE EXCEPTION 'Rollback reopened betting'; END IF;
  UPDATE public.matches SET status='forfeit',winner_team_id=home WHERE id=m3;
  EXECUTE 'SET LOCAL ROLE authenticated';
  UPDATE public.seasons SET status='archived' WHERE id=season;
  BEGIN PERFORM public.confirm_pickle_settlement(m,preview->>'fingerprint',2); RAISE EXCEPTION 'Archived payout changed'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_FINAL:%' THEN RAISE; END IF; END;
  BEGIN DELETE FROM public.matches WHERE id=m; RAISE EXCEPTION 'Award source deleted'; EXCEPTION WHEN foreign_key_violation OR restrict_violation THEN NULL; END;
  EXECUTE 'RESET ROLE';
  IF (SELECT sum(amount) FROM public.pickle_transactions WHERE kind IN('bet','reversal') AND league_id=league)<>0 THEN RAISE EXCEPTION 'Points not conserved'; END IF;
  IF EXISTS(SELECT 1 FROM public.pickle_wallets w WHERE w.league_id=league AND w.balance<>(SELECT coalesce(sum(amount),0) FROM public.pickle_transactions t WHERE t.league_id=w.league_id AND t.pool_player_id=w.pool_player_id)) THEN RAISE EXCEPTION 'Wallet and journal disagree'; END IF;
  SELECT jsonb_agg(to_jsonb(w) ORDER BY pool_player_id) INTO balances_before FROM public.pickle_wallets w WHERE league_id=league;
  SELECT count(*) INTO journal_count FROM public.pickle_transactions WHERE league_id=league;
  BEGIN DELETE FROM public.player_accounts WHERE pool_player_id=ids[5]; RAISE EXCEPTION 'Direct unlink bypassed RPC'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  BEGIN UPDATE public.player_accounts SET pool_player_id=ids[2] WHERE pool_player_id=ids[5]; RAISE EXCEPTION 'Direct relink bypassed RPC'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  PERFORM public.unlink_player_account(ids[5],'BETTOR-1@test.local',unlink_request);
  IF EXISTS(SELECT 1 FROM public.player_accounts WHERE pool_player_id=ids[5]) THEN RAISE EXCEPTION 'Unlink did not revoke account'; END IF;
  IF balances_before IS DISTINCT FROM (SELECT jsonb_agg(to_jsonb(w) ORDER BY pool_player_id) FROM public.pickle_wallets w WHERE league_id=league) OR journal_count<>(SELECT count(*) FROM public.pickle_transactions WHERE league_id=league) THEN RAISE EXCEPTION 'Unlink changed points or history'; END IF;
  IF NOT EXISTS(SELECT 1 FROM pickle_private.account_unlink_receipts WHERE request_id=unlink_request AND user_id=users[1] AND removed_by=admin AND linked_at IS NOT NULL) THEN RAISE EXCEPTION 'Unlink audit missing'; END IF;
  IF EXISTS(SELECT 1 FROM pickle_private.account_unlink_context) THEN RAISE EXCEPTION 'Unlink context retained'; END IF;
  EXECUTE 'SET LOCAL ROLE authenticated';
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[1])::text,true);
  IF public.my_player_account() IS NOT NULL THEN RAISE EXCEPTION 'Old account retained ownership'; END IF;
  BEGIN PERFORM public.pickle_wallet(league); RAISE EXCEPTION 'Unlinked account read private wallet'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  BEGIN PERFORM public.pickle_wallet_history(league); RAISE EXCEPTION 'Unlinked account read history'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  BEGIN PERFORM public.create_pickle_bet(m3,home,1000,1000,gen_random_uuid()); RAISE EXCEPTION 'Unlinked account placed bet'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  BEGIN INSERT INTO pickle_private.account_unlink_context VALUES(txid_current(),users[2],ids[6]); RAISE EXCEPTION 'Unlink context forged'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin,'app_metadata',jsonb_build_object('role','admin'))::text,true);
  PERFORM public.link_player_account(ids[5],'bettor-1@test.local');
  PERFORM public.unlink_player_account(ids[5],'bettor-1@test.local',unlink_request);
  BEGIN PERFORM public.unlink_player_account(ids[6],'bettor-2@test.local',unlink_request); RAISE EXCEPTION 'Changed unlink request accepted'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_REQUEST:%' THEN RAISE; END IF; END;
  BEGIN PERFORM public.unlink_player_account(ids[5],'bettor-2@test.local',gen_random_uuid()); RAISE EXCEPTION 'Stale email unlinked replacement'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_LINK_CHANGED:%' THEN RAISE; END IF; END;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',users[1])::text,true);
  IF (public.my_player_account()->>'playerId')::uuid<>ids[5] OR (public.pickle_wallet(league)->>'owed')::numeric<>5000 THEN RAISE EXCEPTION 'Relink or safe retry lost debt'; END IF;
  EXECUTE 'SET LOCAL ROLE anon';
  BEGIN PERFORM public.unlink_player_account(ids[5],'bettor-1@test.local',gen_random_uuid()); RAISE EXCEPTION 'Anonymous unlinked account'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  EXECUTE 'RESET ROLE';
  BEGIN DELETE FROM pickle_private.account_unlink_receipts WHERE request_id=unlink_request; RAISE EXCEPTION 'Audit deleted'; EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'BET_IMMUTABLE:%' THEN RAISE; END IF; END;
END $$;
ROLLBACK;
